package solution
import("regexp";"strings")
func ResolvePolicy(p,k string,r map[string]map[string]string)(string,bool){if !regexp.MustCompile(`^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$`).MatchString(k)||!strings.HasPrefix(p,"/"){return "",false};clean:=map[string]map[string]string{};for raw,v:=range r{if !strings.HasPrefix(raw,"/"){return "",false};n:=strings.TrimRight(raw,"/");if n==""{n="/"};if _,ok:=clean[n];ok{return "",false};clean[n]=v};p=strings.TrimRight(p,"/");if p==""{p="/"};for{if x:=clean[p];x!=nil{if v,ok:=x[k];ok{return v,true};if v,ok:=x["*"];ok{return v,true}};if p=="/"{return "DENY",true};i:=strings.LastIndex(p,"/");p=p[:i];if p==""{p="/"}}}
